/*
  настройки.js — ЧИСЛА И АДРЕСА. Всё, что настраивается, но не читается
  человеком с экрана.

  Чем отличается от соседей: в мир.js лежит содержание (страницы,
  лавки, тексты), здесь — параметры (сколько нужно протянуть пальцем,
  чтобы страница перелистнулась, какого размера места за столом).
  В ход.js не должно быть ни того, ни другого.
*/

window.МИР_НАСТРОЙКИ = {

  /* ── ХРАНЕНИЕ ────────────────────────────────────────────────────────
     Герой берётся из шага 1: ключ тот же самый, и это намеренно —
     обе страницы лежат на одном адресе и делят память браузера.    */
  хранение: {
    ключГероя: 'вэрн.герой.1',
    ключМира: 'вэрн.мир.1',      // где ты сидишь и в какой очереди
    версияЗаписи: 1
  },

  /* ── ЛИСТАНИЕ СТРАНИЦ ───────────────────────────────────────────────
     Свайп есть, но кнопки-стрелки обязательны: на слабых телефонах
     жест срывается, и человек застревает.                           */
  листание: {
    порогПальца: 60,        // на сколько точек протянуть, чтобы сработало
    порогОтклонения: 45     // если вертикаль больше — это прокрутка, не листание
  },

  /* ── ЗНАК ────────────────────────────────────────────────────────── */
  /*  СЛУЖЕБНЫЕ ИМЕНА для узлов, которые логика собирает руками.
      Живут здесь, а не в логике: строка с буквами в логике — это
      текст, а тексты живут в мир.js. Совпадают с оформлением.     */
  имена: {
    знак: 'знак',
    вПлашке: 'span',
    вВоротах: 'div',
    реплика: 'реплика',
    репликаМоя: 'реплика моя'
  },

  знак: {
    холст: '0 0 24 24',
    толщинаЛинии: 1.5,
    вКарточке: 18,
    уОбитателя: 14,
    вКвартале: 16
  },

  /* ── КАРТА МИРА ──────────────────────────────────────────────────
     Числа из docs/тз-карта.md. Радиусы колец и цены лежат в мир.js:
     они относятся к содержанию, а не к устройству.                  */
  карта: {
    холст: 1900,           // сторона квадрата мира
    центр: 950,            // Сердце в середине
    полныйОборот: 360,     // чтобы в коде не было градусов числом
    точекНаКруге: 360,     // кольцо строится ломаной: так длина по углу
                           // считается точно, без гаданий про дуги
    отступДома: 78,        // от дороги до середины дома
    ширинаДома: 92,
    высотаЭтажа: 26,
    крыша: 30,
    порогКлика: 8,         // из симулятора: палец проехал больше — это
                           // было перетаскивание, а не нажатие
    указательМс: 5000,     // полоса гаснет сама
    кадрМакс: 0.05,        // длиннее кадра не считаем: после сна вкладки
                           // герой иначе прыгнет через полкарты
    мсВСекунде: 1000,

    /* Доли, из которых складывается дом. Всё от ширины и высоты этажа,
       чтобы дом любой этажности собирался сам. */
    дом: {
      теньСправа: 0.62,    // с какой доли ширины начинается тёмная стена
      окноЛево: 0.16, окноПраво: 0.62, окноШирина: 0.2,
      окноСверху: 0.28, окноВысота: 0.44,
      трубаЛево: 0.7, трубаШирина: 0.1, трубаСверху: 0.18, трубаВысота: 0.6,
      каркасОтступ: 6, каркасКрая: 2, каркасЭтажей: 2,
      подписьВыше: 0.7, значокСлева: 40, значокРазмер: 24,
      значокСверху: 13, текстСдвиг: 8, втораяСтрока: 13
    },

    /* Столб: своя ловушка для пальца — сама фигура тонкая. */
    /* Ловушка столба больше самой фигуры: она тонкая, а пальцу нужно
       не меньше 44 точек на экране. При обзоре 700 это ~90 единиц. */
    столб: { ловушкаОтступ: 13, ловушкаЗапас: 26 },

    /*  ФИГУРКА ГЕРОЯ. Доли от роста, начало отсчёта — под ногами.

        Собирается из трёх цветов записи героя: плащ, кожа, волосы,
        плюс знак народа. Портрет к ней отношения не имеет: он 512
        точек и приходит из сети, а фигурка нужна всегда и рисуется
        кодом. Уменьшенный портрет на этом размере стал бы пятном.

        Свет слева сверху — как у всех построек. Оттого правая пола
        плаща затемнена, а не обе.                                 */
    /*  СТЕНА ВОКРУГ ГОРОДА.

        Стоит за внешними домами: третье кольцо на 830, дома снаружи
        него на 908, земля города кончается на 986. Стена начинается с
        1010 — между нею и домами остаётся полоса земли.

        Дороги за третье кольцо не ведут, поэтому герой к ней вплотную
        не подходит: ближайшая точка сети от стены в сотне единиц.

        Толщина взята не на глаз: при обзоре 700 и телефоне в 390
        точек одна единица мира — это 0.56 точки экрана. Стена в 70
        единиц даёт 39 точек, зубец в 26 — почти 15. Ниточкой не
        выглядит.

        За стеной — сплошной камень до края холста. Там край мира, и
        он не должен читаться ни обрывом, ни пустотой.              */
    стена: {
      внутри: 1010,          // где начинается кладка
      толщина: 70,
      зубец: 26,             // сколько зубец выступает наружу
      зубцов: 96,            // по всему кругу
      доляЗубца: 0.55,       // какую часть шага занимает сам зубец
      светОт: 225,           // откуда свет: слева сверху
      ворот: [30, 120, 210, 300],   // концы лучей, поровну по кругу
      воротаПоУглу: 7,       // половина ширины ворот в градусах
      створка: 0.42,         // какую часть проёма занимает одна створка

      /*  На сколько отрезков ломать дуги. Кольцо города строится
          ломаной по той же причине: так длина по углу считается
          точно. Здесь достаточно грубее — дуги короткие.         */
      шаговЗубца: 2,
      шаговВорот: 8,
      шаговСтворки: 6,
      шаговСвета: 60,
      полукруг: 90            // светлая половина: дуга в обе стороны от света
    },

    /*  СВОБОДНОЕ ХОЖДЕНИЕ. Нажал в любое место — идёт туда по дорогам.

        `дальше` — за сколько единиц от ближайшей дороги нажатие
        перестаёт считаться вовсе. Без этого тычок в угол карты уводил
        бы героя через полмира. Геометрия такая: между кольцами 270 и
        260 единиц, то есть от середины до дороги 135; между соседними
        лучами на среднем кольце — около 129. Сто двадцать накрывают
        почти всё, где дороги вообще есть, и отсекают Сердце и лес.

        `грубыйШаг` и `уточнений` — как ищется ближайшая точка: сперва
        проход по длине дороги, потом деления пополам вокруг лучшего.
        Одного грубого прохода мало: на кольце в 1900 единиц метка
        встала бы заметно в стороне от того места, куда придёт герой. */
    /*  Что считается цветом в записи героя. Всё прочее — не цвет, и
        вместо него берётся запасной: запись правится руками.      */
    цветПравило: /^#[0-9a-fA-F]{3,8}$/,

    хождение: {
      дальше: 120,
      грубыйШаг: 20,
      уточнений: 7,
      меткаРадиус: 9,
      меткаТолщина: 2.4,
      меткаЛуч: 5          // длина крестика внутри кольца метки
    },

    фигура: {
      теньШирина: 0.36, теньВысота: 0.11,
      подол: 0.05,          // низ плаща над самой землёй
      плечи: 0.74,          // верх плаща
      полуширина: 0.30,     // половина ширины подола
      затемнение: 0.25,     // насколько темнее правая пола
      голова: 0.88,
      головаРадиус: 0.17,
      ободок: 0.045,        // золотая обводка головы: без неё тёмная
                            // кожа гарнаха сливается с ночной картой
      знакРазмер: 0.26,     // знак народа на плаще
      знакВерх: 0.42,
      знакХолст: 24,        // система координат знаков из мир.js
      знакТолщина: 2.6,

      /*  МЕДАЛЬОН — лицо героя над фигуркой.

          Живая генерация под каждого героя отменена: лицо приходит из
          библиотеки, а на карте фигурка рисуется кодом. Медальон —
          единственное место, где это лицо видно в мире.

          Радиус даётся в долях роста. При росте 64 и обзоре камеры
          700 это ровно те 26 точек экрана, на которых мерялась
          обрезка по голове.                                        */
      медальонРадиус: 0.20,
      медальонВерх: 1.24,   // над макушкой, не задевая головы
      медальонОправа: 0.035,

      /*  Имя обрезки для кружка. Служебное, человеку не видно, но
          живёт здесь: в логике строк с буквами быть не должно.    */
      медальонКлип: 'кружок-лица',
      медальонИмя: 'медальон-героя',
      медальонВписать: 'xMidYMid slice',
      безЗаливки: 'none'
    }
  },

  /* ── ДВИЖЕНИЕ ГЕРОЯ ──────────────────────────────────────────────
     У героя нет координат: есть дорога и пройденный по ней путь.
     Точку считает браузер через getPointAtLength.                   */
  ход: {
    предел: 230,           // точек в секунду на кольце
    луч: 0.85,             // на луче медленнее
    тропка: 0.55,          // на тропке ещё медленнее
    разгон: 900,           // точек в секунду за секунду
    торможение: 1.6,       // во столько раз резче разгона
    качаниеДелитель: 12,   // походка: sin(пройдено / 12) × размах
    качаниеРазмах: 3,
    ростГероя: 64
  },

  /* ── КАМЕРА ──────────────────────────────────────────────────────── */
  камера: {
    плавность: 0.13,       // доля пути к цели за кадр
    /*  Ширина видимого куска мира.

        Считается от пальца, а не на глаз: дом шириной 92 единицы на
        экране в 360 точек должен быть не меньше 44 точек, иначе в него
        не попасть. 92 × 360 / 700 ≈ 47 — проходит с запасом.        */
    обзор: 700
  },

  /* ── СТОЛ ────────────────────────────────────────────────────────────
     Места раскладываются по кругу. Радиус и размер места — доли от
     ширины круга, чтобы всё считалось от одного числа.              */
  стол: {
    радиусДоля: 0.38,       // как далеко место от середины
    местоДоля: 0.26,        // размер одного места
    середина: 0.5,          // где середина круга
    // откуда начинается круг, долями полного оборота: -0.25 это сверху
    уголНачалаДоля: -0.25
  },

  /* ── ШАХМАТЫ ─────────────────────────────────────────────────────── */
  шахматы: {
    клеток: 8,
    /* Знаки фигур. Взяты сплошные для обеих сторон, а цвет даётся
       оформлением: полые знаки на тёмной доске почти не видны. */
    фигуры: { k: '♚', q: '♛', r: '♜', b: '♝', n: '♞', p: '♟' },
    // буквы, которыми библиотека называет фигуры при превращении пешки
    превращение: ['q', 'r', 'b', 'n']
  },

  /* ── ЛАВКИ ────────────────────────────────────────────────────────
     Три первые лавки: шахматы, таро, круг года. Все три работают без
     сети — ни ключей, ни сервисов. Разбор — docs/тз-лавки-первые.md. */
  лавки: {

    /*  Какое занятие на вывеске открывает какую лавку. Занятия, которых
        здесь нет, дают обычное окошко: лавка ещё не построена.       */
    чем: { шахматы: 'шахматы', таро: 'таро', гороскопы: 'круг' },

    /*  РАЗБРОС. Обычный генератор случайных чисел здесь не годится:
        расклад обязан быть ОДИНАКОВЫМ у одного человека в один день,
        иначе доверие рушится с первого повторного захода. Поэтому
        числа выводятся из даты и зерна героя — это тот самый
        линейный конгруэнтный генератор, одинаковый везде.           */
    разброс: { множитель: 1664525, слагаемое: 1013904223, предел: 4294967296 },
    хеш: { основание: 31 },

    /*  Знак Голоса рисуется на холсте 64×96, как значки занятий.    */
    знакШирина: 64,
    знакВысота: 96,
    знакТолщина: 2.6,

    /*  Перевёрнутым Голос выпадает примерно в трети случаев.        */
    долиПеревёрнутых: 0.34,

    /*  Луна. Синодический месяц и точка отсчёта — новолуние
        6 января 2000 года. Формула, а не сервис.                    */
    луна: { месяцСуток: 29.530588853, началоОтсчёта: Date.UTC(2000, 0, 6, 18, 14),
            сутокМс: 86400000 },

    /*  Год Вэрна: тринадцать месяцев по двадцать восемь суток.      */
    год: { месяцев: 13, сутокВМесяце: 28 },

    /*  Сколько раскладов в сутки бесплатно.                         */
    раскладовВСутки: 1,
    ключРаскладов: 'вэрн.расклады'
  },

  /*  ── ЗАПАСНЫЕ ЦВЕТА ФИГУРКИ ────────────────────────────────────
      Фигурка красится тремя цветами из записи героя. Эти значения
      подставляются, только когда записи нет вовсе — мир обязан
      открываться и без героя.

      Здесь раньше лежала тема Телеграма. Она убрана вместе с ходом
      к его серверу: у половины людей там светлая тема, и весь тёплый
      уголь рассыпался бы. Гамма мира задана в стиль.821f58db.css и не зависит
      ни от кого.                                                    */
  цвета: {
    плащПоУмолчанию:   '#6b4a22',
    кожаПоУмолчанию:   '#c9a274',
    волосыПоУмолчанию: '#3a3a3a'
  }
};
